#!/usr/bin/env python3
"""
Round 122b (culprits), 2 October 2026. Needs round 121b.

Every company and financial institution Forest 500 has assessed, and its
2022 country selection.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = "## Round 122b (2 October)\n\nNeeds round 121b. Tiles patch round122b_tiles.py beside it. No app.js?v= bump.\n\n- Every company and financial institution Forest 500 has assessed, 2014 to\n  2025, from the owner's downloads and Forest 500's API: forest500_companies\n  (882) and forest500_institutions (515), one point each at the capital of the\n  headquarters country (spread), coloured by the last total score, filtered by\n  commodity and role, every year's score in the box. Plus the 2022 country\n  selection: forest500_producer_countries (deforested area as the sheet gives\n  it; its heading says thousand hectares but the figures read as hectares) and\n  forest500_trading_countries (total rank, reverse). All four under\n  Deforestation > Companies and financiers, after dff. Built by\n  culprits-tiles-more scripts/forest500_map.py.\n- Forest 500's files hold no amounts of money, so forest500_soy_money (121b) is\n  gone and site_forest500_soy is back in both soy lists.\n- test.mjs: round 122b block; 121b block updated.\n\n"
HEAD = "## Round 122b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round122b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 121b" not in text:
        sys.exit("round122b: round 121b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round122b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round122b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round122b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        # Above the newest note, whichever chat wrote it.
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
